  _ = `Cipta Acara atau Pengumuman baharu`,
  _ = `Draf (tersembunyi, tidak diterbitkan)`,
  _ = `Ini ialah senarai acara yang telah disimpan dan masih sedang diedit. Acara ini tidak boleh dilihat oleh pelanggan dan hanya boleh dilihat oleh ahli pasukan komuniti permainan anda yang lain. Apabila acara ini tersedia, anda perlu menerbitkannya sebelum pelanggan Steam boleh melihatnya.`,
  _ = `Acara Berjadual (tersembunyi, diterbitkan)`,
  _ = `Ini ialah senarai acara yang telah dijadualkan dan sedia untuk dipaparkan secara automatik pada masa akan datang yang ditetapkan. Anda boleh terus mengedit acara ini jika anda perlu membuat kemas kini.`,
  _ = `Acara Tidak Tersenarai (diterbitkan, boleh dilihat dengan pautan langsung)`,
  _ = `Acara ini hanya boleh dilihat oleh pengguna yang mempunyai pautan langsung kepada acara tersebut. Acara ini tidak dipaparkan dalam sebarang senarai atau dipautkan secara automatik daripada mana-mana bahagian sistem acara.`,
  _ = `Acara Boleh Dilihat Secara Umum (boleh dilihat, diterbitkan)`,
  _ = `Ini ialah senarai acara yang boleh dilihat oleh semua pelanggan Steam di pelbagai tempat pada gedung, komuniti dan dalam pustaka Steam mereka. Tatal ke bawah untuk memuatkan lagi.`,
  _ = `Ditampilkan`,
  _ = `Acara ini ditandakan sebagai "ditampilkan". Acara "ditampilkan" yang paling terkini akan muncul diserlahkan kepada pemain di bahagian atas halaman pustaka permainan anda.`,
  _ = `Akan Datang`,
  _ = `Aktif`,
  _ = `Baru Dimulakan`,
  _ = `Muatkan Lagi Acara Terdahulu`,
  _ = `Muatkan Lagi Acara Akan Datang`,
  _ = `Tiada acara dalam mod draf.`,
  _ = `Tiada acara yang dijadualkan untuk disiarkan pada masa akan datang.`,
  _ = `Tiada Acara yang boleh dilihat secara umum untuk permainan ini.`,
  _ = `Semua acara awam dimuatkan dan ditunjukkan di atas`,
  _ = `Ralat telah berlaku semasa meminta lebih banyak acara dan pengumuman. Sila cuba lagi nanti.`,
  _ = `Kembali ke Papan Pemuka`,
  _ = `Akaun Penerbitan Acara: %1$s`,
  _ = `Eksport Statistik Acara`,
  _ = `Eksport fail .csv yang mengandungi statistik tanggapan dan tontonan untuk semua acara yang disiarkan dalam julat masa yang ditetapkan.`,
  _ = `Permulaan julat`,
