  _ = `Memproses: %1$s`,
  _ = `E-mel`,
  _ = `Hantar sebagai e-mel`,
  _ = `Hantar juga e-mel tentang kemas kini ini kepada pemain?`,
  _ = `Pratonton: Hantar e-mel ini kepada saya`,
  _ = `Sediakan E-mel Untuk Dihantar kepada Pelanggan`,
  _ = `Mula menghantar E-mel`,
  _ = `Subjek E-mel:`,
  _ = `Teks Butang:`,
  _ = `Destinasi:`,
  _ = `URL Halaman Jualan:`,
  _ = `Kami hanya menyokong kemasukan URL sah yang bermula dengan alamat https://store.steampowered.com/ address.`,
  _ = `Tukar URL halaman jualan gedung`,
