  _ = `<username>`,
  _ = `Anda menerima e-mel ini kerana anda telah bermain`,
  _ = `Anda menerima e-mel ini kerana anda mengikuti %1$s di Steam`,
  _ = `Anda menerima e-mel ini kerana anda bermain permainan dalam siri %1$s`,
  _ = `Anda menerima e-mel ini kerana anda telah memasukkan %1$s ke dalam senarai hajat di Steam`,
  _ = `Kami menghantar e-mel pemberitahuan acara ini kepada anda kerana anda telah bermain:`,
  _ = `Kami menghantar e-mel pemberitahuan acara ini kepada anda kerana anda telah mengikuti:`,
  _ = `Kami menghantar e-mel pemberitahuan acara ini kepada anda kerana anda telah bermain permainan dalam siri:`,
  _ = `Kami menghantar e-mel pemberitahuan acara ini kepada anda kerana anda telah menambahkan yang berikut pada senarai hajat anda:`,
  _ = `%1$s di Steam`,
  _ = `Jika anda memilih untuk tidak menerima pemberitahuan permainan tertentu pada masa hadapan, anda boleh`,
  _ = `Abaikan e-mel daripada %1$s sahaja`,
  _ = `atau`,
  _ = `edit pilihan e-mel anda untuk berhenti melanggan`,
  _ = `© Valve Corporation.  PO Box 1688 Bellevue, WA 98009.`,
  _ = `Hak cipta terpelihara. Semua tanda dagangan ialah hak milik pemilik masing-masing di AS dan negara-negara lain.`,
  _ = `Hantar E-mel Ujian`,
  _ = `Tidak dapat menghantar e-mel ujian. E-mel anda belum disahkan dengan Steam. Sila sahkan e-mel anda di sini: %1$s`,
  _ = `Perubahan pada e-mel tidak disimpan. Sila simpan perubahan sebelum mencetuskan e-mel pratonton.`,
  _ = `Hantar e-mel ke alamat e-mel yang dikaitkan dengan akaun anda? Jika alamat itu salah, kemas kini alamat e-mel anda di sini: %1$s`,
  _ = `Pilih Imej Penjenamaan`,
  _ = `%1$spx x %2$spx`,
  _ = `Penapis Akaun`,
  _ = `Setiap pengguna yang dipilih perlu memenuhi kriteria penapis ini untuk menerima pemberitahuan.`,
  _ = `Aplikasi berada dalam Top N dalam Cadangan Interaktif Steam`,
  _ = `Kecualikan pengguna yang mempunyai permainan dalam senarai hajat mereka`,
  _ = `Kawalan Eksperimen untuk Menahan pemberitahuan daripada`,
  _ = `Penerima`,
  _ = `E-mel ini patut dihantar kepada siapa?`,
  _ = `Semua pemain yang ada dalam permainan anda`,
  _ = `Mereka yang mahukan permainan anda`,
  _ = `Pengikut permainan anda`,
  _ = `Kecualikan Pemilik permainan anda`,
  _ = `Pemilik tanpa sebarang masa bermain`,
  _ = `Pengikut laman utama pencipta %1$s anda`,
  _ = `Pemain permainan yang dipautkan ke laman utama pencipta %1$s anda`,
  _ = `Tiada laman utama pencipta yang dipautkan ke permainan ini, mengehadkan potensi e-mel. Ketahui lebih lanjut di sini: %1$s`,
  _ = `Kandungan untuk bahasa tidak lengkap untuk %1$s. Bahagian %2$s daripada %3$s telah diisi.`,
  _ = `E-mel ini memerlukan karya seni penjenamaan dalam Bahasa Inggeris. E-mel tidak boleh dihantar tanpa karya seni Bahasa Inggeris.`,
  _ = `Anda perlu memilih sekurang-kurangnya satu kumpulan penerima untuk menerima e-mel`,
  _ = `E-mel tidak mempunyai teks`,
  _ = `Dalam bahagian penerima, anda mesti memilih sekurang-kurangnya satu kotak pilihan antara hak pembangun atau penerbit.`,
  _ = `URL Youtube telah dinyatakan tetapi tidak boleh dihuraikan. Sila semak URL video tersebut`,
  _ = `E-mel tidak boleh disediakan dan dihantar sehingga acara asas diterbitkan dan disiarkan secara langsung. Sila terbitkan acara terlebih dahulu.`,
  _ = `E-mel mempunyai penyetempatan %1$s tanpa karya seni penjenamaan yang sepadan dalam bahasa tersebut. Karya seni penjenamaan Bahasa Inggeris akan digunakan sebagai sandaran.`,
  _ = `E-mel mempunyai penyetempatan untuk %1$s dan %2$s tanpa karya seni penjenamaan yang sepadan untuk bahasa tersebut. Karya seni penjenamaan Bahasa Inggeris akan digunakan sebagai sandaran.`,
  _ = `E-mel mempunyai penyetempatan untuk %1$s, %2$s dan %3$s bahasa lagi tanpa karya seni penjenamaan yang sepadan untuk bahasa tersebut. Karya seni penjenamaan Bahasa Inggeris akan digunakan sebagai sandaran.`,
  _ = `E-mel mempunyai penyetempatan untuk bahasa %1$s tetapi tiada karya seni penjenamaan yang sepadan untuk bahasa tersebut.`,
  _ = `Menyediakan E-mel`,
  _ = `Acara ini mempunyai perubahan yang belum disimpan. Sila simpan acara tersebut sebelum bersedia untuk menghantar e-mel ini`,
  _ = `E-mel sedia untuk dihantar. Adakah anda bersedia untuk mengunci e-mel bagi mengelakkan sebarang perubahan lagi? Tindakan ini tidak akan menghantar e-mel, tetapi hanya menyediakannya untuk dihantar apabila anda sudah bersedia.`,
  _ = `Kami menemui amaran berikut. Anda boleh memilih untuk membetulkannya sebelum mengunci kandungan e-mel.`,
  _ = `Sebagai sebahagian daripada persediaan, kami menemui ralat berikut yang akan menghalang penghantaran e-mel:`,
  _ = `Sila tunggu sementara e-mel disediakan`,
  _ = `Persediaan Selesai. Anda boleh menghantar e-mel apabila bersedia.`,
  _ = `Hubungi Valve untuk menghantar e-mel`,
  _ = `E-mel ujian telah dimasukkan dalam baris gilir untuk dihantar. Anda sepatutnya menerimanya sebentar lagi.`,
  _ = `Halaman Steam Store untuk DLC: %1$s (%2$s)`,
  _ = `Mengambil Maklumat DLC`,
