  _ = `Skor ulasan`,
  _ = `Pengguna serentak`,
  _ = `Kiraan hasil minimum untuk seksyen`,
  _ = `Hanya paparkan seksyen ini jika pengguna mempunyai banyak item ini atau lebih yang sepadan dengan halaman dan tag`,
  _ = `Rawakkan`,
  _ = `Tanya tentang set hasil yang lebih besar daripada katalog dan kemudian mengembalikan pilihan rawak untuk item tersebut. Medan isihan masih relevan jika terdapat lebih banyak item yang lulus penapis daripada had hasil.`,
  _ = `Tunjukkan acara terkini dan pengumuman daripada permainan pilihan.`,
  _ = `Tunjukkan acara dan pengumuman terkini dari semua permainan, lebih mengutamakan permainan yang dimiliki/diikuti/dalam senarai hajat kemudian kembali kepada penjual terlaris.`,
  _ = `Tunjukkan acara dan pengumuman terkini. <1>Lihat dan siarkan acara baharu</1>`,
