  _ = `Lumpuhkan varian mudah alih dan kosongkan tetapannya`,
  _ = `Varian Mudah Alih ialah tetapan pilihan yang membenarkan penyesuaian menyeluruh untuk media grid ini apabila dipaparkan dalam susun atur mudah alih. Ini membolehkan penyediaan teks, seni dan kawalan yang berbeza untuk paparan mudah alih`,
