  _ = `Lumpuhkan varian tablet dan kosongkan tetapannya`,
  _ = `Varian Tablet adalah tetapan pilihan yang membolehkan penyesuaian menyeluruh untuk media grid ini apabila dipaparkan dalam susun atur tablet atau Steam Deck dan peranti yang serupa. Ini membolehkan menyediakan teks, seni dan kawalan yang berbeza untuk paparan tablet`,
