  _ = `Nama Lencana`,
  _ = `Penerangan Awal Lencana`,
  _ = `Terangkan mekanik asas untuk memperoleh lencana kepada pelanggan yang belum menerimanya. Ini akan dipaparkan kepada pengguna yang tidak log masuk juga. Mereka akan diminta untuk log masuk untuk maju ke lencana.`,
  _ = `Arahan kemajuan lencana`,
  _ = `Sekarang pengguna mempunyai lencana awal, ini boleh mencadangkan bantuan tambahan untuk memajukan lencana ke tahap seterusnya.`,
  _ = `Arahan kemajuan lencana - Tahap maksimum dicapai`,
  _ = `Ini ialah tahap lencana maksimum yang kami jangkakan boleh dicapai secara munasabah oleh pelanggan biasa. Jika boleh, arahan boleh mencadangkan tindakan lain untuk meningkatkan tahap selanjutnya. `,
  _ = `Tahap Lencana dan URL`,
  _ = `Tahap #`,
  _ = `URL Imej Lencana`,
  _ = `Aset mungkin wujud dalam komuniti dan hendaklah bersaiz 160x160 piksel. Anda boleh menggunakan bentuk pendek {IMG_URL}/badges/... untuk merujuk kepada imej.`,
  _ = `(Pilihan) URL Imej Lencana Hantu`,
  _ = `Aset pilihan yang jika ditetapkan, akan dipaparkan kepada pengguna SEBELUM mereka memperoleh lencana sebenar. Ini berguna apabila anda ingin menyembunyikan butiran khusus mengenai lencana sebelum ia diperoleh. Aset hendaklah 160x160 px.`,
  _ = `Tambah Tahap dan Baris URL`,
  _ = `ID Lencana Pengguna (khusus acara)`,
  _ = `Tahap lencana diberikan apabila Baris Gilir Penemuan dilengkapkan di halaman jualan ini`,
  _ = `Ini menjangkakan baris gilir penemuan tersedia pada halaman jualan terlebih dahulu. Lencana akan dikemas kini secara dinamik apabila baris gilir selesai dan pemberian lencana akan dihantar ke halaman ringkasan baris gilir penemuan.`,
  _ = `Editor Kemajuan Pencarian`,
