  _ = `Editor untuk mengaitkan acara ganjaran item maya dan memilih ganjaran khusus untuk dipaparkan kepada pengguna. Kita boleh memuatkan ganjaran yang tersedia dan memilih ganjaran yang muncul dalam senarai.`,
