  _ = `Kumpulan Item`,
  _ = `Jenis kumpulan yang item ini tergolong. Membuka pintu akan memberikan satu item daripada setiap kumpulan yang diliputi. Oleh itu, jika sesebuah kumpulan mempunyai lebih daripada satu item, hanya satu item sahaja yang akan diberikan secara rawak. Berikan setiap item kumpulan tersendiri melainkan jika anda berniat untuk menjadikannya sebagai pilihan alternatif.`,
